   var imported=Store.Initial();var existing=b.Copy();existing.Name="保留已有备注";existing.Note="FAKE_NOTE";existing.Password="FAKE_EXISTING_SECRET";imported.Accounts.Add(existing);string existingId=existing.Id;int added=GlobalImport.Merge(imported,new[]{new KeyValuePair<string,string>("A",a.LoginAccount),new KeyValuePair<string,string>("B",b.LoginAccount.ToUpperInvariant())});check(added==1&&imported.Accounts.Count==2&&existing.Id==existingId&&existing.Name=="保留已有备注"&&existing.Password=="FAKE_EXISTING_SECRET"&&existing.Note=="FAKE_NOTE","A/B 导入按邮箱去重，保留旧标识、密码、名称及备忘");
